ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    struct hid_gadget *hid;
    ssize_t ret = 0;
    int status;

    hid = file->private_data;
    if (!hid)
        return -ENODEV;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock_irq(&hid->write_queue_lock);

    while (!hid->write_pending) {
        status = wait_event_interruptible(hid->write_wq, hid->write_pending);
        if (status < 0) {
            ret = status;
            goto out;
        }
    }

    if (copy_from_user(hid->write_req->buf, buffer, count)) {
        ret = -EFAULT;
        goto out;
    }

    hid->write_req->length = count;
    usb_ep_queue(hid->ep_out, hid->write_req, GFP_ATOMIC);
    hid->write_pending = false;

    ret = count;
    wake_up(&hid->write_wq);

out:
    spin_unlock_irq(&hid->write_queue_lock);
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    struct hid_gadget *gadget = file->private_data;
    ssize_t ret = 0;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock_irq(&gadget->write_queue_lock);

    while (atomic_read(&gadget->write_pending)) {
        DECLARE_WAITQUEUE(wait, current);
        add_wait_queue(&gadget->write_wait, &wait);
        set_current_state(TASK_INTERRUPTIBLE);

        spin_unlock_irq(&gadget->write_queue_lock);
        schedule();
        remove_wait_queue(&gadget->write_wait, &wait);

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }

        spin_lock_irq(&gadget->write_queue_lock);
    }

    atomic_set(&gadget->write_pending, 1);

    if (copy_from_user(gadget->write_req->buf, buffer, count)) {
        ret = -EFAULT;
        goto unlock;
    }

    gadget->write_req->length = count;
    usb_ep_queue(gadget->ep, gadget->write_req, GFP_ATOMIC);

    atomic_set(&gadget->write_pending, 0);
    wake_up(&gadget->write_queue_wait);

    ret = count;

unlock:
    spin_unlock_irq(&gadget->write_queue_lock);
out:
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    struct hid_gadget_dev *gdev = file->private_data;
    ssize_t ret = 0;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock_irq(&gdev->qlock);

    while (gdev->write_pending) {
        ret = wait_event_interruptible(gdev->waitq, !gdev->write_pending);
        if (ret < 0)
            goto out;
    }

    ret = -ENOMEM;
    gdev->write_pending = true;

    ret = usbhid_submit_output(gdev, buffer, count);
    if (ret < 0) {
        gdev->write_pending = false;
        ret = -EIO;
        goto out;
    }

    ret = count;

    wake_up(&gdev->waitq);

out:
    spin_unlock_irq(&gdev->qlock);
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    ssize_t ret;

    if (!access_ok(buffer, count))
        return -EFAULT;

    spin_lock(&write_queue_lock);

    while (write_pending) {
        wait_event(write_queue_wait, !write_pending);
    }

    ret = copy_from_user(write_request->buf, buffer, count);
    if (ret) {
        ret = -EFAULT;
        spin_unlock(&write_queue_lock);
        return ret;
    }

    write_request->length = count;

    if (!queue_write_request(write_request)) {
        ret = -EIO;
        write_pending = false;
        wake_up(&write_queue_wait);
    }

    spin_unlock(&write_queue_lock);
    return count;
}
